const fs = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('INPUT_PATH is required');
let csvContent;
try {
  csvContent = fs.readFileSync(inputPath, 'utf8');
} catch (e) {
  throw new Error('Failed to read input file: ' + e.message);
}
if (!csvContent || csvContent.trim().length === 0) {
  throw new Error('Input CSV file is empty');
}
globalThis.csvContent = csvContent;

const converter = await import('json-2-csv');
const csv2json = converter.csv2json || (converter.default && converter.default.csv2json);
if (typeof csv2json !== 'function') throw new Error('csv2json is not a function');
let data;
try {
  data = await csv2json(globalThis.csvContent);
} catch (e) {
  throw new Error('Failed to parse CSV: ' + e.message);
}
if (!Array.isArray(data) || data.length === 0) {
  throw new Error('CSV did not parse to a non-empty array');
}
const keys = Object.keys(data[0]);
const escapeCell = (val) => {
  if (val === null || val === undefined) return '';
  return String(val).replace(/\|/g, '\\|').replace(/\n/g, '<br>');
};
let md = '| ' + keys.map(k => escapeCell(k)).join(' | ') + ' |\n';
md += '|' + keys.map(() => ' --- ').join('|') + '|\n';
for (const row of data) {
  md += '| ' + keys.map(k => escapeCell(row[k])).join(' | ') + ' |\n';
}
globalThis.markdownOutput = md;

const fs = await import('node:fs');
const outputPath = process.env.OUTPUT_PATH;
if (!outputPath) throw new Error('OUTPUT_PATH is required');
try {
  fs.writeFileSync(outputPath, globalThis.markdownOutput, 'utf8');
} catch (e) {
  throw new Error('Failed to write output file: ' + e.message);
}
console.log(JSON.stringify({ output_path: outputPath }));
